"""Build the single-file English demo from final research tables and offline geometry."""
from pathlib import Path
import pandas as pd,json,math
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[1] if HERE.parent.name=='04_reproduce' else HERE.parents[1]/'repo2'
E=ROOT/'03_evidence';OUT=ROOT/'02_demo/index.html'
def rows(path):
 d=pd.read_csv(path,dtype={'fips':str});return json.loads(d.to_json(orient='records'))
def main():
 raw=rows(E/'conus_county_screening.csv')
 counties=[{'fips':r['fips'].zfill(5),'name':r['name'],'state':r['state'],'source':r['source'],'analog':r['analog_class'],'nearest':r['nearest_study'],'distance':r['distance']} for r in raw]
 cards=[]
 keys=['fips','county','state','crop','bias_pct','skill_vs_county_climatology','irrigated_fraction_2022','corn_silage_share_2022','corn_after_soy_pct','corn_after_corn_pct']
 for r in rows(E/'county_evidence_cards.csv'):cards.append({k:r[k] for k in keys})
 evidence=[
 {'id':'E1','title':'Observed Marsden system contrasts','support':'96 crop/year/block pairs in 2006–2017. In the held-out 2012–2017 period, three-year minus two-year system means are +10.22 bu/ac for corn and +6.17 for soybean.','limit':'One trial site; fertilizer, manure and other practices differ. These are system contrasts, not isolated crop-function effects or farm forecasts.','sources':[{'label':'Davis et al. 2012','url':'https://doi.org/10.1371/journal.pone.0047149'},{'label':'Pinned maRsden author repository','url':'https://github.com/vanichols/maRsden/tree/01476a18c01115f70f154cf7e94c1951205fbda1'}]},
 {'id':'E2','title':'Rye on five Iowa farms','support':'PFI 2022 published treatment means, reported LSD, dates, biomass and water descriptions. Includes nonsignificant and negative outcomes.','limit':'Raw strip measurements and sensor series were not acquired. Date conflicts, sensor failures and the Ose conclusion/Table 3 contradiction remain visible.','sources':[{'label':'PFI original research report','url':'https://practicalfarmers.org/resources/research-reports/cover-crop-effect-on-soil-water/'}]},
 {'id':'E3','title':'Source-driven field replay','support':'32 actual Rust runs use four 2014 corn plots, two SOC/OM assumptions and four initial-water fractions. Original soil profiles and main N events support input checks.','limit':'Not an official APSIM run. Retention and initial states remain partly assumed; yield is low and water storage high. Conservation is not predictive validation.','sources':[{'label':'Lazicki et al. 2016 soil and root data','url':'https://doi.org/10.1371/journal.pone.0164209'},{'label':'Saxton & Rawls retention-prior method','url':'https://doi.org/10.2136/sssaj2005.0117'}]},
 {'id':'E4','title':'Actual county crop context','support':'Six-county evidence combines sampled CDL predecessor cells, county yields, irrigation and available grain/silage information.','limit':'Sample shares are not field boundaries or area weights. Irrigation, product use, true rotations, cultivars and management still need local confirmation.','sources':[{'label':'USDA NASS crop and yield statistics','url':'https://www.nass.usda.gov/'},{'label':'USDA Cropland Data Layer documentation','url':'https://www.nass.usda.gov/Research_and_Science/Cropland/sarsfaqs2.php'}]},
 {'id':'E5','title':'Historical transfer validation','support':'Nine county-crop series: 7/9 have negative temporal-holdout skill (median −0.31); 8/9 have negative leave-one-year-out skill (median −0.96).','limit':'Historical hindcasts are not a new prospective field validation. A county mean or a regional bias adjustment does not resolve domain mismatch.','sources':[{'label':'NASA POWER forcing context','url':'https://power.larc.nasa.gov/'},{'label':'USDA NASS observations','url':'https://www.nass.usda.gov/'}]},
 {'id':'E6','title':'Conditional historical economics','support':'Equal-phase annualization of published 2008–2012 estimated management returns. GE and Non-GE technology packages produce different financial point-estimate orders.','limit':'Not a current-price forecast, complete CBA, a claim of statistical superiority or a farmer recommendation. Costs, buyers and transition accounts remain open.','sources':[{'label':'Mulik 2015 conference paper','url':'https://ageconsearch.umn.edu/record/205805'}]},
 {'id':'E7','title':'Climate resemblance and map coverage','support':'Final county table: 3,107 records, with 885 POWER sample labels, 2,216 IDW-filled labels and six study anchors. Available outlines cover 3,098 records; the other nine remain searchable.','limit':'Relative classes are climate-distance quantiles, not suitability probabilities. No national process-model run or nationwide rotation recommendation is supplied.','sources':[{'label':'NASA POWER climatology','url':'https://power.larc.nasa.gov/'},{'label':'us-atlas boundary geometry','url':'https://github.com/topojson/us-atlas'}]}
 ]
 sites=[{'fips':'19015','name':'Boone County, Iowa','short':'Boone, IA','dx':8,'dy':-12},{'fips':'20013','name':'Brown County, Kansas','short':'Brown, KS','dx':8,'dy':-5},{'fips':'20161','name':'Riley County, Kansas','short':'Riley, KS','dx':8,'dy':14},{'fips':'20169','name':'Saline County, Kansas','short':'Saline, KS','dx':-52,'dy':-10},{'fips':'16027','name':'Canyon County, Idaho','short':'Canyon, ID','dx':-61,'dy':-10},{'fips':'16045','name':'Gem County, Idaho','short':'Gem, ID','dx':8,'dy':-12},{'fips':'16083','name':'Twin Falls County, Idaho','short':'Twin Falls, ID','dx':7,'dy':12}]
 process=ROOT/'04_reproduce/case-study/field-admission-v2/processed'
 data={'counties':counties,'map':[{k:r[k] for k in ['fips','path','cx','cy']} for r in json.loads((HERE/'map_paths.json').read_text())],'states':[],'sites':sites,'cards':cards,'annual':rows(E/'marsden_annual_contrasts.csv'),'contrasts':rows(E/'contrast_summary.csv'),'pfi':rows(E/'pfi_2022_farm_summary.csv'),'finance':rows(E/'historical_financial_point_order.csv'),'yieldMetrics':rows(process/'field_replay_yield_metrics.csv'),'waterMetrics':rows(process/'field_replay_water_metrics.csv'),'facts':json.loads((E/'summary_facts.json').read_text()),'evidence':evidence}
 data['evidenceData']={'E1':{'contrasts':data['contrasts'],'annual':data['annual']},'E2':data['pfi'],'E3':data['facts']['latest_process'],'E4':cards,'E5':rows(E/'historical_validation_series.csv'),'E6':data['finance'],'E7':{'source_counts':data['facts']['final_screening_csv_source_counts'],'records':len(counties),'outlines':len(data['map'])}}
 assert len(counties)==3107 and len(data['map'])==3098
 template=(HERE/'template.html').read_text();output=template.replace('/*STYLE*/',(HERE/'style.css').read_text()).replace('/*DATA*/',json.dumps(data,ensure_ascii=False,separators=(',',':'),allow_nan=False).replace('<','\\u003c')).replace('/*SCRIPT*/',(HERE/'app.js').read_text())
 OUT.write_text(output);print(json.dumps({'output':str(OUT),'bytes':OUT.stat().st_size,'counties':len(counties),'outlines':len(data['map']),'external_runtime_requests':0}))
if __name__=='__main__':main()
